-- Los hilos de Messenger que se guardaron como Instagram.
--
-- ============================================================================
-- QUÉ PASÓ
-- ============================================================================
--
-- Las dos suscripciones de la aplicación de Meta apuntaban a la MISMA dirección.
-- Consultado el 22 de septiembre de 2026:
--
--     GET /{app-id}/subscriptions
--     → object: "instagram"  callback_url: …/api/instagram/webhook
--       object: "page"       callback_url: …/api/instagram/webhook
--
-- El lector de cargas no miraba el campo `object` —Meta manda la misma forma
-- para los dos—, así que todo lo que llegó por Messenger se guardó con
-- `canal = 'instagram'`, con la ficha enlazada al canal Instagram, y con el
-- nombre buscado en el Graph de Instagram usando un PSID de Facebook. Eso
-- último no puede funcionar nunca: de ahí los hilos titulados con un número.
--
-- El código ya no se equivoca —`lib/meta/canales.ts` decide por `object`—, pero
-- lo que entró antes sigue mal etiquetado. Esto lo acomoda.
--
-- ============================================================================
-- CÓMO SE SABE CUÁLES SON
-- ============================================================================
--
-- No se puede adivinar mirando el número: un PSID de Facebook y un IGSID de
-- Instagram son los dos números largos que asigna Meta y no hay forma de
-- distinguirlos por la forma. Así que no se adivina: la lista de abajo son los
-- identificadores que la PROPIA Página de la escuela reconoce como
-- conversaciones de Messenger, leídos de Meta el 22 de septiembre de 2026 con
-- el token de Página:
--
--     GET /107321267902102/conversations?platform=messenger&fields=participants
--
-- Son 800 conversaciones. La mayoría no están en el CRM —son de antes de
-- conectar el webhook— y para ésas esto no hace nada. Las que sí están son las
-- que hay que mover.
--
-- ============================================================================
-- QUÉ NO TOCA
-- ============================================================================
--
-- Los mensajes no se tocan: siguen colgando de su conversación y los archivos
-- adjuntos siguen en la carpeta `ig/` del mismo bucket. Mover los archivos
-- obligaría a reescribir `media_ruta` de cada mensaje para ganar una carpeta
-- más prolija, y una ruta mal reescrita es una foto que el asesor ya no ve.
--
-- Es idempotente: correrlo dos veces no cambia nada la segunda vez.

begin;

create temporary table _psids (identificador text primary key) on commit drop;

on conflict do nothing;

-- ---------------------------------------------------------------------------
-- 1. Los hilos que hay que mover, y los que NO se pueden mover.
-- ---------------------------------------------------------------------------
--
-- Un hilo no se mueve si esa misma persona YA tiene un hilo de Messenger: la
-- tabla tiene `(canal, identificador)` como único y el cambio chocaría. Puede
-- pasar con quien escribió antes y después del arreglo. Se dejan afuera y se
-- listan al final, porque fundir dos hilos es una decisión de quien vende
-- —cuál conversación vale— y no de una migración.

create temporary table _mover on commit drop as
  select c.id, c.identificador
    from public.conversaciones c
    join _psids p on p.identificador = c.identificador
   where c.canal = 'instagram'
     and not exists (
       select 1 from public.conversaciones otra
        where otra.canal = 'messenger'
          and otra.identificador = c.identificador
     );

update public.conversaciones c
   set canal = 'messenger'
  from _mover m
 where c.id = m.id;

-- ---------------------------------------------------------------------------
-- 2. La ficha del cliente, enlazada al canal correcto.
-- ---------------------------------------------------------------------------
--
-- `contactos_canal` dice por qué canales llegó cada persona. Si queda apuntando
-- a Instagram, la ficha va a decir «llegó por Instagram» para siempre y la
-- línea de tiempo va a poner la etiqueta equivocada en cada mensaje.
--
-- Misma cautela: si esa persona ya tiene su fila de Messenger, se borra la de
-- Instagram en vez de moverla —la llave es `(cliente_id, canal_id)`— y se
-- conserva la fecha más vieja de las dos, que es cuando de verdad apareció.

update public.contactos_canal cc
   set primera_vez = least(cc.primera_vez, vieja.primera_vez),
       ultima_vez = greatest(cc.ultima_vez, vieja.ultima_vez)
  from public.contactos_canal vieja
  join _psids p on p.identificador = vieja.identificador
 where vieja.canal_id = (select id from public.canales where nombre = 'Instagram')
   and cc.canal_id = (select id from public.canales where nombre = 'Messenger')
   and cc.cliente_id = vieja.cliente_id;

delete from public.contactos_canal cc
 using _psids p
 where cc.identificador = p.identificador
   and cc.canal_id = (select id from public.canales where nombre = 'Instagram')
   and exists (
     select 1 from public.contactos_canal otra
      where otra.cliente_id = cc.cliente_id
        and otra.canal_id = (select id from public.canales where nombre = 'Messenger')
   );

update public.contactos_canal cc
   set canal_id = (select id from public.canales where nombre = 'Messenger')
  from _psids p
 where cc.identificador = p.identificador
   and cc.canal_id = (select id from public.canales where nombre = 'Instagram');

-- ---------------------------------------------------------------------------
-- 3. Qué se hizo, para que quede a la vista al correrlo.
-- ---------------------------------------------------------------------------

do $$
declare
  movidos int;
  chocaron int;
begin
  select count(*) into movidos from _mover;

  select count(*) into chocaron
    from public.conversaciones c
    join _psids p on p.identificador = c.identificador
   where c.canal = 'instagram';

  raise notice 'Hilos movidos de Instagram a Messenger: %', movidos;

  if chocaron > 0 then
    raise notice 'Quedaron % hilos sin mover porque esa persona ya tenía uno de Messenger.', chocaron;
    raise notice 'Aparecen en Clientes → Duplicados sugeridos para unificarlos a mano.';
  end if;
end $$;

commit;
